ALTER TABLE public.operational_calendar_entries ADD COLUMN IF NOT EXISTS area_type text CHECK (area_type IN ('academia','quadra','piscina','brinquedoteca','salao','outro'));
CREATE TABLE IF NOT EXISTS public.area_reservations (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
 aluno_id uuid not null references public.alunos(id) on delete cascade, area_type text not null check(area_type in ('academia','quadra','piscina','brinquedoteca','salao','outro')),
 title text not null, starts_at timestamptz not null, ends_at timestamptz not null, status text not null default 'confirmada' check(status in ('confirmada','cancelada','concluida')), created_at timestamptz not null default now(), check(ends_at > starts_at));
CREATE INDEX IF NOT EXISTS area_reservations_org_area_time ON public.area_reservations(organization_id,area_type,starts_at);
ALTER TABLE public.area_reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY area_reservations_resident ON public.area_reservations FOR SELECT TO authenticated USING (public.is_admin(auth.uid()) OR exists(select 1 from public.alunos a where a.id=area_reservations.aluno_id and a.user_id=auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=area_reservations.organization_id and m.user_id=auth.uid() and m.papel::text in ('admin','manager','sindico','professor')));
CREATE TABLE IF NOT EXISTS public.service_requests (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
 aluno_id uuid not null references public.alunos(id) on delete cascade, service_type text not null check(service_type in ('personal','nutricao','avaliacao','aula_particular','evento')),
 requested_at timestamptz not null default now(), preferred_at timestamptz, status text not null default 'solicitada' check(status in ('solicitada','cotada','confirmada','concluida','cancelada')),
 assigned_to text, quoted_value numeric(12,2), payment_id uuid references public.pagamentos(id), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS service_requests_org_status ON public.service_requests(organization_id,status,created_at desc);
ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_requests_resident_read ON public.service_requests FOR SELECT TO authenticated USING (public.is_admin(auth.uid()) OR exists(select 1 from public.alunos a where a.id=service_requests.aluno_id and a.user_id=auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=service_requests.organization_id and m.user_id=auth.uid() and m.papel::text in ('admin','manager','sindico','professor')));
CREATE OR REPLACE FUNCTION public.create_area_reservation(p_organization_id uuid,p_area_type text,p_title text,p_starts_at timestamptz,p_ends_at timestamptz) RETURNS public.area_reservations LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_student uuid; v_row public.area_reservations; BEGIN SELECT id INTO v_student FROM public.alunos WHERE user_id=auth.uid() AND organization_id=p_organization_id LIMIT 1; IF v_student IS NULL OR p_area_type NOT IN ('academia','quadra','piscina','brinquedoteca','salao','outro') OR p_ends_at<=p_starts_at THEN RAISE EXCEPTION 'Reserva inválida'; END IF; IF EXISTS(SELECT 1 FROM public.area_reservations WHERE organization_id=p_organization_id AND area_type=p_area_type AND status='confirmada' AND tstzrange(starts_at,ends_at,'[)') && tstzrange(p_starts_at,p_ends_at,'[)')) THEN RAISE EXCEPTION 'Este horário já está reservado'; END IF; INSERT INTO public.area_reservations(organization_id,aluno_id,area_type,title,starts_at,ends_at) VALUES(p_organization_id,v_student,p_area_type,btrim(p_title),p_starts_at,p_ends_at) RETURNING * INTO v_row; RETURN v_row; END $$;
CREATE OR REPLACE FUNCTION public.create_service_request(p_organization_id uuid,p_service_type text,p_preferred_at timestamptz default null,p_notes text default null) RETURNS public.service_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_student uuid; v_row public.service_requests; BEGIN SELECT id INTO v_student FROM public.alunos WHERE user_id=auth.uid() AND organization_id=p_organization_id LIMIT 1; IF v_student IS NULL OR p_service_type NOT IN ('personal','nutricao','avaliacao','aula_particular','evento') THEN RAISE EXCEPTION 'Solicitação inválida'; END IF; INSERT INTO public.service_requests(organization_id,aluno_id,service_type,preferred_at,notes) VALUES(p_organization_id,v_student,p_service_type,p_preferred_at,p_notes) RETURNING * INTO v_row; RETURN v_row; END $$;
CREATE OR REPLACE FUNCTION public.quote_service_request(p_id uuid,p_value numeric,p_assigned_to text,p_preferred_at timestamptz default null) RETURNS public.service_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.service_requests; v_payment uuid; BEGIN SELECT * INTO v FROM public.service_requests WHERE id=p_id FOR UPDATE; IF NOT FOUND OR NOT(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=v.organization_id and m.user_id=auth.uid() and m.papel::text in ('admin','manager','sindico','professor'))) THEN RAISE EXCEPTION 'Sem permissão'; END IF; INSERT INTO public.pagamentos(aluno_id,valor,data_vencimento,status,referencia_mes,observacoes) VALUES(v.aluno_id,p_value,current_date,'pendente',date_trunc('month',current_date)::date,'Serviço NINE LIVING: '||v.service_type) RETURNING id INTO v_payment; UPDATE public.service_requests SET status='cotada',quoted_value=p_value,assigned_to=p_assigned_to,preferred_at=coalesce(p_preferred_at,preferred_at),payment_id=v_payment,updated_at=now() WHERE id=p_id RETURNING * INTO v; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.create_area_reservation(uuid,text,text,timestamptz,timestamptz),public.create_service_request(uuid,text,timestamptz,text),public.quote_service_request(uuid,numeric,text,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_area_reservation(uuid,text,text,timestamptz,timestamptz),public.create_service_request(uuid,text,timestamptz,text),public.quote_service_request(uuid,numeric,text,timestamptz) TO authenticated;

